function buildDock(){const D=$('#dock'),M=mob(),list=M?['about','projects','resume','contact']:ORDER;D.innerHTML=(M?'':`<button class="dk" data-app="launchpad" aria-label="Launchpad">${ico('launchpad')}<span class="tp">Launchpad</span><i class="rd"></i></button>`)+list.map(a=>`<button class="dk" data-app="${a}" aria-label="${APPS[a].name}">${ico(a)}<span class="tp">${APPS[a].name}</span><i class="rd"></i></button>`).join('')+(M?'':`<span class="sep"></span><button class="dk hm" data-app="trash" aria-label="Trash">${ico('trash')}<span class="tp">Trash</span><i class="rd"></i></button>`);
$$('.dk',D).forEach(b=>{b.onclick=()=>b.dataset.app==='launchpad'?openLP():launch(b.dataset.app);b.oncontextmenu=e=>{e.preventDefault();const a=b.dataset.app,run=W.has(a);ctx(e.clientX,e.clientY-90,[[ 'Open',()=>launch(a)],run?['Close Window',()=>close(a)]:['Not running',()=>{},'',true]])}});dockState()}
function dockState(){$$('.dk').forEach(b=>{const a=b.dataset.app;b.classList.toggle('run',[...W.values()].some(w=>w.app===a||(a==='projects'&&w.app==='proj')))})}
(()=>{const D=$('#dock');let raf=0;D.addEventListener('mousemove',e=>{if(!PF.mag||mob()||OS.dataset.motion==='off')return;cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>$$('.dk',D).forEach(b=>{const r=b.getBoundingClientRect(),d=Math.abs(e.clientX-(r.left+r.width/2)),s=1+.65*Math.pow(Math.max(0,1-d/120),2);b.style.transform=`scale(${s.toFixed(3)})`;b.style.margin=`0 ${((s-1)*20).toFixed(1)}px`}))});D.addEventListener('mouseleave',()=>{cancelAnimationFrame(raf);$$('.dk',D).forEach(b=>{b.style.transform='';b.style.margin=''})})})();
(()=>{const D=$('#dock'),L=$('.wpl');D.addEventListener('pointermove',e=>D.style.setProperty('--sx',(e.clientX-D.getBoundingClientRect().left)+'px'));let r=0;addEventListener('pointermove',e=>{if(mob()||OS.dataset.motion==='off'||r)return;r=requestAnimationFrame(()=>{r=0;L.style.setProperty('--px',((e.clientX/vw()-.5)*-14).toFixed(1)+'px');L.style.setProperty('--py',((e.clientY/vh()-.5)*-14).toFixed(1)+'px')})},{passive:true})})();
const IPOS=()=>{const v=ls.get('pos_ic',{});return v&&typeof v==='object'?v:{}};
function layoutIcons(){const ic=$('#ic'),M=mob(),pos=IPOS(),rows=Math.max(1,Math.floor((vh()-MB-110)/108));$$('.di',ic).forEach((d,i)=>{if(M){d.style.left=d.style.top='';return}const q0=pos[d.dataset.app],p=q0&&Number.isFinite(q0.x)&&Number.isFinite(q0.y)?q0:{x:vw()-108-Math.floor(i/rows)*104,y:MB+12+(i%rows)*108};d.style.left=clamp(p.x,0,vw()-96)+'px';d.style.top=clamp(p.y,MB,vh()-110)+'px'})}
function buildIcons(){const ic=$('#ic');ic.innerHTML=ORDER.map(a=>`<button class="di" data-app="${a}" aria-label="${APPS[a].name}">${ico(a)}<span>${APPS[a].name}</span></button>`).join('');
$$('.di',ic).forEach(d=>{const a=d.dataset.app;d.onclick=e=>{e.stopPropagation();$$('.di').forEach(x=>x.classList.toggle('sel',x===d));if(mob())launch(a)};d.ondblclick=()=>launch(a);d.onkeydown=e=>{if(e.key==='Enter')launch(a)};d.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();$$('.di').forEach(x=>x.classList.toggle('sel',x===d));ctx(e.clientX,e.clientY,[['Open',()=>launch(a)],['Get Info',()=>notify(APPS[a].name,'Double-click or press Enter to open',a)]])};
d.onpointerdown=e=>{if(mob()||e.button)return;const sx=e.clientX,sy=e.clientY,ox=d.offsetLeft,oy=d.offsetTop;let moved=false;d.setPointerCapture(e.pointerId);const mv=ev=>{const dx=ev.clientX-sx,dy=ev.clientY-sy;if(!moved&&Math.hypot(dx,dy)<5)return;moved=true;d.style.left=clamp(ox+dx,0,vw()-96)+'px';d.style.top=clamp(oy+dy,MB,vh()-110)+'px'},up=()=>{d.removeEventListener('pointermove',mv);d.removeEventListener('pointerup',up);if(moved){const gx=Math.round(d.offsetLeft/12)*12,gy=Math.round(d.offsetTop/12)*12;d.style.left=gx+'px';d.style.top=gy+'px';const p=IPOS();p[a]={x:gx,y:gy};ls.set('pos_ic',p);d.dataset.m=1;setTimeout(()=>delete d.dataset.m,50)}};d.addEventListener('pointermove',mv);d.addEventListener('pointerup',up)}});layoutIcons()}
function resetLayout(){ls.set('pos_ic',{});try{sessionStorage.removeItem('pos_w')}catch(e){}layoutIcons();W.forEach(w=>{Object.assign(w,{x:bx(),y:MB+26,w:Math.min(APPS[w.app].w,vw()-40),h:Math.min(APPS[w.app].h,vh()-MB-dockH()-30),max:false});w.el.classList.remove('mx');fit(w);w.el.classList.add('anim');place(w);setTimeout(()=>w.el.classList.remove('anim'),320)});notify('Layout reset','Icons and windows returned to defaults','settings')}
// context menu + desktop
function closeCtx(){const c=$('#cx');c&&c.remove()}
function ctx(x,y,items){closeCtx();closeMenu();showItems('cx',x,y,items)}
$('#desk').oncontextmenu=e=>{if(e.target.closest('.win,.di'))return;e.preventDefault();ctx(e.clientX,e.clientY,[['New Terminal',()=>launch('terminal')],['Change Wallpaper',()=>setPF('wall',(PF.wall+1)%4,'Wallpaper changed')],['Mission Control',openMC,'⇧⌘F'],['Reset Layout',resetLayout],['Settings…',()=>launch('settings')]])};
