// ---------- spotlight + mission control ----------
const spIdx=()=>[...ORDER.concat(['trash']).map(k=>({t:APPS[k].name,s:'Application',run:()=>launch(k)})),...P.map((p,i)=>({t:p.n,s:'Project · '+CATS[p.c],k:p.d+' '+p.t.join(' '),run:()=>launch('proj',{id:'proj:'+i,i})})),...SK.flatMap(([c,l])=>l.map(x=>({t:x,s:'Skill · '+c,run:()=>launch('skills')}))),{t:'Manav Rachna International Institute (MRIIRS)',s:'Education',k:'btech cgpa 2028',run:()=>launch('education')},...EXP.map(e=>({t:e.t,s:'Experience · '+e.o,k:e.x,run:()=>launch('experience')})),...ACH.map(a=>({t:a[0],s:'Achievement',k:a[1],run:()=>launch('achievements')}))];
let spR=[],spI=0,lastF=null;
function openSP(){closeOverlays();lastF=document.activeElement;const s=document.createElement('div');s.id='sp';s.setAttribute('role','dialog');s.setAttribute('aria-label','Spotlight search');s.innerHTML='<div class="spb"><input placeholder="Spotlight Search" aria-label="Spotlight search" autocomplete="off"><ul id="sr" role="listbox"></ul></div>';OS.append(s);const inp=$('input',s),ix=spIdx();
const rl=()=>{const q=inp.value.toLowerCase().trim();spR=(q?ix.filter(r=>(r.t+' '+(r.k||'')+' '+r.s).toLowerCase().includes(q)):ix.slice(0,ORDER.length)).slice(0,30);spI=0;$('#sr').innerHTML=spR.length?spR.map((r,i)=>`<li role="option" data-i="${i}" class="${i?'':'s'}">${esc(r.t)}<small>${esc(r.s)}</small></li>`).join(''):'<li class="mut">No results</li>'};
inp.oninput=rl;rl();inp.focus();s.onclick=e=>{if(e.target===s)closeOverlays()};$('#sr').onclick=e=>{const l=e.target.closest('li[data-i]');if(l)runSP(+l.dataset.i)};
inp.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();runSP(spI)}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();spI=clamp(spI+(e.key==='ArrowDown'?1:-1),0,spR.length-1);$$('#sr li').forEach((l,i)=>{l.classList.toggle('s',i===spI);if(i===spI)l.scrollIntoView({block:'nearest'})})}}}
function runSP(i){const r=spR[i];if(r){closeOverlays();r.run()}}
function openMC(){closeOverlays();lastF=document.activeElement;const m=document.createElement('div');m.id='mc';m.setAttribute('role','dialog');m.setAttribute('aria-label','Mission Control');const L=[...W.values()];m.innerHTML=L.length?`<div class="mcg">${L.map(w=>`<button class="mcc" data-id="${esc(w.id)}">${ico(w.app==='proj'?'proj':w.app)}<b>${esc(w.title)}</b><span class="mut">${w.min?'Minimized':'Open'}</span></button>`).join('')}</div>`:'<div class="mut" style="font-size:18px">No open windows. Press Esc and double-click an app to start.</div>';OS.append(m);const f0=$('.mcc',m);f0&&f0.focus();m.onkeydown=e=>{const cs=$$('.mcc',m),i=cs.indexOf(document.activeElement);if(e.key==='ArrowRight'||e.key==='ArrowDown'){e.preventDefault();(cs[i+1]||cs[0]).focus()}else if(e.key==='ArrowLeft'||e.key==='ArrowUp'){e.preventDefault();(cs[i-1]||cs[cs.length-1]).focus()}};m.onclick=e=>{const b=e.target.closest('.mcc');if(b){closeOverlays();W.get(b.dataset.id).min?restore(b.dataset.id):focus(b.dataset.id)}else closeOverlays()}}
function closeOverlays(keep){['#sp','#mc','#lp','#lk','#ql','#nc'].forEach(q=>{const e=$(q);e&&e.remove()});closeMenu();closeCtx();closeCC();if(!keep&&lastF&&document.contains(lastF)&&lastF.focus)lastF.focus();lastF=null}
addEventListener('keydown',e=>{const k=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;if(mod&&k==='k'){e.preventDefault();$('#sp')?closeOverlays():openSP()}else if(mod&&e.shiftKey&&k==='f'){e.preventDefault();$('#mc')?closeOverlays():openMC()}else if(k==='escape'){if($('#sp,#mc,#dd,#cx,#cc,#lp,#lk,#ql,#nc'))closeOverlays()}else if((mod||e.altKey)&&k==='w'&&act){e.preventDefault();close(act)}else if((mod||e.altKey)&&k==='m'&&act){e.preventDefault();minimize(act)}});
// ---------- widgets, notification center, launchpad, lock screen, quick look, snapping ----------
function calHTML(d){const y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1).getDay(),n=new Date(y,m+1,0).getDate();let h=`<div class="cal"><b>${new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(d)}</b><div class="cg">${['S','M','T','W','T','F','S'].map(x=>`<span class="mut">${x}</span>`).join('')}`;for(let i=0;i<first;i++)h+='<span></span>';for(let i=1;i<=n;i++)h+=`<span class="${i===d.getDate()?'td':''}">${i}</span>`;return h+'</div></div>'}
function buildWidgets(){$('#wg').innerHTML=`<div class="wgt clock"><svg viewBox="0 0 100 100" role="img" aria-label="Analog clock"><circle cx="50" cy="50" r="46" class="face"/>${[...Array(12)].map((_,i)=>`<line x1="50" y1="8" x2="50" y2="${i%3?11:15}" transform="rotate(${i*30} 50 50)"/>`).join('')}<line id="hh" x1="50" y1="50" x2="50" y2="29"/><line id="hm" x1="50" y1="50" x2="50" y2="18"/><line id="hs" x1="50" y1="56" x2="50" y2="14" class="sec"/></svg></div><div class="wgt" data-cal></div><div class="wgt"><b>Now building</b><div class="mut">SkillBridge, a full-stack product (in progress)</div></div>`}
let calD='';function wgTick(n){const h=$('#hh');if(!h)return;const s=n.getSeconds(),m=n.getMinutes()+s/60,hr=(n.getHours()%12)+m/60;h.setAttribute('transform',`rotate(${hr*30} 50 50)`);$('#hm').setAttribute('transform',`rotate(${m*6} 50 50)`);$('#hs').setAttribute('transform',`rotate(${s*6} 50 50)`);const k=n.toDateString();if(k!==calD){calD=k;$('[data-cal]').innerHTML=calHTML(n)}}
function closeNC(){const p=$('#nc');p&&p.remove()}
function toggleNC(){if($('#nc')){closeNC();return}closeMenu();closeCC();const p=document.createElement('aside');p.id='nc';p.setAttribute('aria-label','Notification Center');p.innerHTML=`<h3>${fmtD.format(new Date())}</h3>${calHTML(new Date())}<h4>Notifications</h4>${NH.length?NH.map(n=>`<div class="nh">${ico(n.k||'about')}<div><b>${esc(n.t)}</b><div class="mut">${esc(n.m)}</div></div></div>`).join(''):'<p class="mut">No recent notifications</p>'}`;OS.append(p);p.onclick=e=>e.stopPropagation()}
function openLP(){closeOverlays();lastF=document.activeElement;const l=document.createElement('div');l.id='lp';l.setAttribute('role','dialog');l.setAttribute('aria-modal','true');l.setAttribute('aria-label','Launchpad');l.innerHTML=`<input type="search" placeholder="Search" aria-label="Search apps"><div class="lpg">${ORDER.map(a=>`<button data-a="${a}">${ico(a)}<span>${APPS[a].name}</span></button>`).join('')}</div>`;OS.append(l);const inp=$('input',l);inp.focus();l.onclick=e=>{const b=e.target.closest('button[data-a]');if(b){const a=b.dataset.a;closeOverlays();launch(a)}else if(e.target===l)closeOverlays()};inp.oninput=()=>{const q=inp.value.toLowerCase();$$('.lpg button',l).forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q))};inp.onkeydown=e=>{if(e.key==='Enter'){const b=$$('.lpg button',l).find(x=>!x.hidden);if(b)b.click()}}}
function openLK(){closeOverlays();lastF=document.activeElement;const k=document.createElement('div');k.id='lk';k.setAttribute('role','dialog');k.setAttribute('aria-modal','true');k.setAttribute('aria-label','Lock screen');k.innerHTML=`<div><div class="lkd"></div><div class="lkc"></div></div><div class="lku"><div class="ph">PS</div><b>${ME.name}</b><button class="btn p" id="ul">Unlock</button><small class="mut">Guest session · no password needed</small></div>`;OS.append(k);const u=()=>{const d=new Date();$('.lkd',k).textContent=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(d);$('.lkc',k).textContent=fmtT.format(d)};u();const iv=setInterval(()=>{if(!k.isConnected)clearInterval(iv);else u()},1000);const b=$('#ul',k);b.focus();b.onclick=()=>closeOverlays()}
function openQL(i){closeOverlays();lastF=document.activeElement;const p=P[i],q=document.createElement('div');q.id='ql';q.setAttribute('role','dialog');q.setAttribute('aria-modal','true');q.setAttribute('aria-label','Quick Look: '+p.n);q.innerHTML=`<div class="qlb"><img data-fb="shot" draggable="false" referrerpolicy="no-referrer" src="assets/projects/${p.img}" alt="${esc(p.n)} screenshot"><div class="qlt"><b>${esc(p.n)}</b><span class="mut">${CATS[p.c]} · ${esc(p.st)}</span></div></div>`;OS.append(q);q.tabIndex=-1;q.focus();q.onclick=()=>closeOverlays();q.onkeydown=e=>{if(e.key===' '){e.preventDefault();closeOverlays()}}}
const SN=document.createElement('div');SN.id='snap';SN.hidden=true;$('#desk').append(SN);
function snapRect(t){const H=vh()-MB-dockH();return t==='l'?{x:0,y:MB,w:vw()/2,h:H}:t==='r'?{x:vw()/2,y:MB,w:vw()/2,h:H}:{x:0,y:MB,w:vw(),h:H}}
function showSnap(t){if(!t){SN.hidden=true;return}const r=snapRect(t);SN.hidden=false;Object.assign(SN.style,{left:r.x+'px',top:r.y+'px',width:r.w+'px',height:r.h+'px'})}
function snapWin(w,t){if(t==='m'){if(!w.max)maxi(w.id);return}if(!w.max&&!w.prev)w.prev={x:w.x,y:w.y,w:w.w,h:w.h};const r=snapRect(t);Object.assign(w,{x:r.x,y:r.y,w:Math.max(r.w,w.mw),h:r.h,max:false});w.el.classList.remove('mx');w.el.classList.add('anim');place(w);setTimeout(()=>w.el.classList.remove('anim'),320);persist(w.id)}
addEventListener('keydown',e=>{if($('#sp,#mc,#lp,#lk,#ql'))return;if(e.altKey&&!e.ctrlKey&&e.code==='Backquote'){e.preventDefault();const L=[...W.keys()].filter(i=>!W.get(i).min);if(L.length>1)focus(L[(L.indexOf(act)+1)%L.length])}else if(e.ctrlKey&&e.altKey&&act&&!mob()){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();snapWin(W.get(act),e.key==='ArrowLeft'?'l':'r')}else if(e.key==='Enter'){e.preventDefault();maxi(act)}}});
